package com.sky.handler;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

import com.sky.exception.BaseException;
import com.sky.result.Result;

@ExtendWith(MockitoExtension.class)
class GlobalExceptionHandlerTest {

    @InjectMocks
    private GlobalExceptionHandler globalExceptionHandler;

    @Test
    @DisplayName("正向测试：NumberFormatException应返回特定错误消息")
    void testNumberFormatExceptionHandler_ReturnsSpecificErrorMessage() {
        // Arrange
        NumberFormatException exception = new NumberFormatException("For input string: \"abc\"");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertEquals(0, result.getCode());
        assertEquals("参数格式错误，请输入有效的数字", result.getMsg());
    }

    @Test
    @DisplayName("边界测试：空数字格式异常应正确处理")
    void testNumberFormatExceptionHandler_EmptyMessage() {
        // Arrange
        NumberFormatException exception = new NumberFormatException("");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertEquals(0, result.getCode());
        assertEquals("参数格式错误，请输入有效的数字", result.getMsg());
    }

    @Test
    @DisplayName("边界测试：null异常消息的NumberFormatException应正确处理")
    void testNumberFormatExceptionHandler_NullMessage() {
        // Arrange
        NumberFormatException exception = new NumberFormatException(null);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertEquals(0, result.getCode());
        assertEquals("参数格式错误，请输入有效的数字", result.getMsg());
    }

    @Test
    @DisplayName("正向测试：BaseException应返回异常消息")
    void testBaseExceptionHandler_ReturnsExceptionMessage() {
        // Arrange
        String expectedMessage = "业务异常消息";
        BaseException exception = new BaseException(expectedMessage);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertEquals(0, result.getCode());
        assertEquals(expectedMessage, result.getMsg());
    }

    @Test
    @DisplayName("正向测试：MethodArgumentTypeMismatchException应返回特定错误消息")
    void testMethodArgumentTypeMismatchExceptionHandler_ReturnsSpecificErrorMessage() {
        // Arrange
        MethodArgumentTypeMismatchException exception = mock(MethodArgumentTypeMismatchException.class);
        when(exception.getMessage()).thenReturn("参数类型不匹配");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertEquals(0, result.getCode());
        assertEquals("请求参数类型错误", result.getMsg());
    }

    @Test
    @DisplayName("验证不同类型的异常都返回非成功code")
    void testAllExceptionHandlers_ReturnNonSuccessCode() {
        // Test NumberFormatException
        NumberFormatException numberFormatException = new NumberFormatException("test");
        Result<String> result1 = globalExceptionHandler.exceptionHandler(numberFormatException);
        assertNotEquals(1, result1.getCode());

        // Test BaseException
        BaseException baseException = new BaseException("test");
        Result<String> result2 = globalExceptionHandler.exceptionHandler(baseException);
        assertNotEquals(1, result2.getCode());

        // Test MethodArgumentTypeMismatchException
        MethodArgumentTypeMismatchException mismatchException = mock(MethodArgumentTypeMismatchException.class);
        when(mismatchException.getMessage()).thenReturn("test");
        Result<String> result3 = globalExceptionHandler.exceptionHandler(mismatchException);
        assertNotEquals(1, result3.getCode());
    }
}
